package com.enterpriseflow.controller;
import com.enterpriseflow.api.ApiResponse; import com.enterpriseflow.service.WorkspaceService; import com.enterpriseflow.workspace.dto.TaskRequest; import jakarta.validation.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class TaskController {private final WorkspaceService s; public TaskController(WorkspaceService x){s=x;} @GetMapping("/projects/{projectId}/tasks") public ApiResponse<List<Map<String,Object>>> list(Authentication a,@PathVariable UUID projectId,@RequestParam(required=false)String status,@RequestParam(required=false)String priority){return ApiResponse.success("Tasks retrieved.",s.listTasks(a.getName(),projectId,status,priority));}@PostMapping("/projects/{projectId}/tasks") public ApiResponse<Map<String,Object>> create(Authentication a,@PathVariable UUID projectId,@Valid @RequestBody TaskRequest r){return ApiResponse.success("Task created.",s.createTask(a.getName(),projectId,r));}@PutMapping("/tasks/{id}") public ApiResponse<Map<String,Object>> update(Authentication a,@PathVariable UUID id,@Valid @RequestBody TaskRequest r){return ApiResponse.success("Task updated.",s.updateTask(a.getName(),id,r));}@DeleteMapping("/tasks/{id}") public ApiResponse<Void> delete(Authentication a,@PathVariable UUID id){s.deleteTask(a.getName(),id);return ApiResponse.success("Task deleted.",null);}@GetMapping("/tasks/{id}/comments") public ApiResponse<List<Map<String,Object>>> comments(Authentication a,@PathVariable UUID id){return ApiResponse.success("Comments retrieved.",s.comments(a.getName(),id));}@PostMapping("/tasks/{id}/comments") public ApiResponse<Map<String,Object>> comment(Authentication a,@PathVariable UUID id,@RequestBody Map<String,String> b){String c=b.get("content");if(c==null||c.isBlank())throw new IllegalArgumentException("Comment content is required.");return ApiResponse.success("Comment added.",s.comment(a.getName(),id,c));}}
